import numpy as np

def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    base_target = 50.99437557578087  # OPT_PARAM: {"initial": 50.99437557578087, "min": 0.0, "max": 500.0, "type": "float"}
    demand_response_factor = 0.21435398638255154  # OPT_PARAM: {"initial": 0.21435398638255154, "min": 0.0, "max": 2.0, "type": "float"}
    inventory_adjustment = 0.18538428818744934  # OPT_PARAM: {"initial": 0.18538428818744934, "min": 0.0, "max": 1.0, "type": "float"}

    adjusted_target = base_target + demand_response_factor * last_demand
    inventory_position = on_hand_inventory + sum(pipeline_orders)
    order_amount = max(0.0, adjusted_target - inventory_adjustment * inventory_position)

    return order_amount
